import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0014: Why Ordinary Dependency Cycles Are Forbidden","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0014-why-ordinary-dependency-cycles-are-forbidden.md","filePath":"adr/ADR-0014-why-ordinary-dependency-cycles-are-forbidden.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0014-why-ordinary-dependency-cycles-are-forbidden.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0014-why-ordinary-dependency-cycles-are-forbidden" tabindex="-1">ADR-0014: Why Ordinary Dependency Cycles Are Forbidden <a class="header-anchor" href="#adr-0014-why-ordinary-dependency-cycles-are-forbidden" aria-label="Permalink to “ADR-0014: Why Ordinary Dependency Cycles Are Forbidden”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: resources.md §3.5, ADR-0004</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>When A depends on B and B depends on A, the recovery order is logically unsolvable: both sides &quot;wait for the other to become healthy first,&quot; forming mutual waiting. A cycle discovered at runtime manifests as deadlock or arbitrary-order random repairs; configuration errors silently fester.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Ordinary dependency graphs must be acyclic: cycle detection at configuration load time (<code>DependencyGraph::build</code>); a cycle rejects startup and prints the concrete cycle path (<code>a -&gt; b -&gt; a</code>); users cannot &quot;break&quot; cycles with runtime fallbacks. Expressing &quot;mutual backup&quot; legitimately uses <code>alternative_groups</code> (redundancy groups, required_count semantics) instead of cycles.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>Runtime cycle breaking (timeout/arbitration)</strong>: unpredictable behavior; recovery order depends on which side wins the race.</li><li><strong>Allow cycles + tolerant topological sort</strong>: the sort algorithm&#39;s output for cycles is arbitrary — equivalent to random recovery.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: unrecoverable modeling errors rejected once at startup; recovery order is always well-defined (topological sort). Cons: mutual-dependency modeling needs alternative_groups (learning curve).</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li>Conditional dependencies (<code>conditional_on</code>) are special activation edges inside a DAG, also constrained by cycle detection.</li><li>Configuration validation errors must include the full cycle path (tests: rejects_dependency_cycle_at_startup).</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};